{
  "decision-isolate-trading-working-capital": "WITH changes AS (SELECT b.balance_id, b.balance_side, b.closing_cents - b.opening_cents - COALESCE(SUM(m.movement_cents), 0) AS trading_change_cents FROM depot_balance AS b LEFT JOIN depot_move AS m ON m.balance_id = b.balance_id AND m.move_kind IN ('acquired', 'translation') GROUP BY b.balance_id, b.balance_side, b.opening_cents, b.closing_cents) SELECT balance_id, trading_change_cents, CASE WHEN balance_side = 'asset' THEN -trading_change_cents ELSE trading_change_cents END AS operating_adjustment_cents FROM changes ORDER BY balance_id",
  "decision-join-split-page-caption": "SELECT DISTINCT (l.piece || r.piece) COLLATE BINARY AS caption FROM job AS j JOIN fragment AS l ON l.impression = j.impression AND l.side = 'L' AND l.lo = 4 JOIN fragment AS r ON r.impression = j.impression AND r.side = 'R' AND r.lo = l.hi AND r.hi = 12 ORDER BY caption COLLATE BINARY",
  "decision-kiln-cart-dispatch": "WITH loads(departure_no, first_batch, second_batch, load_kg, saved_cents, batch_count) AS (SELECT DISTINCT departure_no, NULL, NULL, 0, 0, 0 FROM kiln_offer UNION ALL SELECT departure_no, batch_code, NULL, mass_kg, delay_cents, 1 FROM kiln_offer WHERE mass_kg <= 10 UNION ALL SELECT a.departure_no, a.batch_code, b.batch_code, a.mass_kg + b.mass_kg, a.delay_cents + b.delay_cents, 2 FROM kiln_offer AS a JOIN kiln_offer AS b ON b.departure_no = a.departure_no AND a.batch_code COLLATE BINARY < b.batch_code WHERE a.mass_kg + b.mass_kg <= 10), ranked AS (SELECT loads.*, ROW_NUMBER() OVER (PARTITION BY departure_no ORDER BY saved_cents DESC, load_kg, batch_count, first_batch COLLATE BINARY, second_batch COLLATE BINARY) AS rn FROM loads) SELECT departure_no, first_batch, second_batch, load_kg, saved_cents FROM ranked WHERE rn = 1 ORDER BY departure_no",
  "decision-kiln-disagreement-by-exposure-time": "WITH intervals AS (SELECT kiln_code, tick_min, left_c, right_c, LEAD(tick_min, 1, 20) OVER (PARTITION BY kiln_code ORDER BY tick_min) AS next_tick FROM probe_pairs), clipped AS (SELECT kiln_code, left_c, right_c, MAX(0, MIN(20, next_tick) - MAX(0, tick_min)) AS minutes FROM intervals) SELECT kiln_code, SUM(CASE WHEN left_c IS NOT NULL AND right_c IS NOT NULL THEN minutes ELSE 0 END) AS covered_minutes, SUM(CASE WHEN ABS(left_c - right_c) >= 5 THEN minutes ELSE 0 END) AS discordant_minutes FROM clipped GROUP BY kiln_code ORDER BY kiln_code"
}
